import React, { useState } from 'react';
import './MalePage.css';

const services = [
  {
    id: 1,
    name: 'Classic Haircut',
    description: 'A timeless haircut tailored to your style.',
    image: 'https://i.pinimg.com/564x/67/68/45/6768456615021905a91c65827836219e.jpg',
  },
  {
    id: 2,
    name: 'Beard Trim',
    description: 'Detailed beard trimming and shaping.',
    image: 'https://i.pinimg.com/564x/03/46/63/03466314d897ebf35b6302177d0f7383.jpg',
  },
  {
    id: 3,
    name: 'Hair Styling',
    description: 'Get the perfect style for any occasion.',
    image: 'https://i.pinimg.com/564x/e7/2e/91/e72e91d19827870a693d377a56d4415f.jpg',
  },
];

const MalePage = () => {
  const [feedback, setFeedback] = useState('');
  const [submittedFeedbacks, setSubmittedFeedbacks] = useState([]);

  const handleFeedbackChange = (e) => {
    setFeedback(e.target.value);
  };

  const handleFeedbackSubmit = () => {
    if (feedback.trim() !== '') {
      setSubmittedFeedbacks([...submittedFeedbacks, feedback]);
      setFeedback('');
    }
  };

  return (
    <div className="male-page">
      <h1 className="title">Men's Services</h1>
      <div className="services-container">
        {services.map((service) => (
          <div key={service.id} className="service-card">
            <img src={service.image} alt={service.name} className="service-image" />
            <h2 className="service-name">{service.name}</h2>
            <p className="service-description">{service.description}</p>
          </div>
        ))}
      </div>

      <div className="feedback-section">
        <h2>Share Your Experience</h2>
        <textarea
          value={feedback}
          onChange={handleFeedbackChange}
          placeholder="Write your feedback here..."
          className="feedback-textarea"
          rows={3}
        />
        <button onClick={handleFeedbackSubmit} className="submit-button">
          Submit
        </button>

        <div className="submitted-feedbacks">
          {submittedFeedbacks.map((item, index) => (
            <p key={index} className="feedback-item">• {item}</p>
          ))}
        </div>
      </div>
    </div>
  );
};

export default MalePage;
